import{normalize,filtered,categories,hours,safeURL}from'./national.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let rows=[],saved=[],savedOnly=false,type='All',label='your selected location',busy=false,truncated=false,loadError='',hasSearched=false;
try{const s=JSON.parse(localStorage.getItem('fff-national-saved')||'[]');if(Array.isArray(s))saved=s.filter(r=>r&&typeof r.id==='string'&&typeof r.name==='string')}catch{}
const sourceName=s=>String(s||'Source not supplied').replaceAll('_',' ');
function sources(){const select=$('#source-filter'),value=select.value;select.replaceChildren(new Option('All record sources','All'));[...new Set((savedOnly?saved:rows).map(r=>r.data_source||''))].sort().forEach(s=>select.add(new Option(sourceName(s),s)));select.value=[...select.options].some(o=>o.value===value)?value:'All';}
function render(){const list=filtered(savedOnly?saved:rows,$('#keyword').value,type,$('#source-filter').value);$('#count').textContent=!hasSearched&&!savedOnly?'Enter an address or ZIP code, or use your location to begin.':loadError&&!savedOnly?'Search unavailable':savedOnly?`${list.length} saved listings · across all your searches`:`${list.length} matching listings within 5 miles of ${label}${truncated?' · provider returns a limited subset; more may exist':''}`;$('#results').innerHTML=list.length?list.map(r=>{const address=[r.address,r.city,r.state,r.zip].filter(Boolean).join(', '),phone=String(r.phone||'').replace(/[^+0-9]/g,''),web=safeURL(r.website),isSaved=saved.some(s=>s.id===r.id);return `<article class="card"><div class="card-top"><span class="tag">${esc(categories[r.resource_type])}</span><span class="distance">${savedOnly?'Saved listing':'≈ '+r.distance.toFixed(1)+' mi'}</span></div><h3>${esc(r.name)}</h3><p class="address">${esc(address||'Address not supplied; check listing')}</p><p class="hours">◷ ${esc(hours(r))}</p><p class="note">${esc(r.requirements_text||'Eligibility and intake requirements not supplied. Contact the provider.')}</p>${r.resource_type==='food_bank'?'<p class="note">Food banks may supply other agencies rather than serve walk-ins. Call first.</p>':''}<div class="actions"><a class="primary" target="_blank" rel="noopener" href="https://www.google.com/maps/dir/?api=1&destination=${encodeURIComponent(address||r.lat+','+r.lng)}">Directions ↗</a>${phone?`<a class="secondary" href="tel:${esc(phone)}">Call provider</a>`:''}${web?`<a class="secondary" href="${esc(web)}" target="_blank" rel="noopener">Website ↗</a>`:''}<button class="secondary" data-save="${esc(r.id)}" aria-label="${isSaved?'Unsave':'Save'} ${esc(r.name)}" aria-pressed="${isSaved}">${isSaved?'♥ Saved':'♡ Save'}</button></div><p class="source">Record source: ${esc(sourceName(r.data_source))}<br>Directory status: ${esc(r.verification_status||'not supplied')} (publisher reported)<br>Record verification date: ${esc(r.last_verified_date||'not supplied')}<br><a href="https://feedam.org/resource/${encodeURIComponent(r.id)}" target="_blank" rel="noopener">View directory record ↗</a> · Always call ahead.</p></article>`}).join(''):`<div class="empty"><h3>${busy?'Searching the national directory…':loadError&&!savedOnly?'Search unavailable':!hasSearched&&!savedOnly?'Find free food near you':'No matching listings to display.'}</h3><p>${busy?'Please wait for the search to finish.':loadError&&!savedOnly?esc(loadError):!hasSearched&&!savedOnly?'Enter a U.S. street address with city and state, a five-digit ZIP code, or choose Use my location.':'Try clearing your filters or another ZIP code. No results does not mean no assistance exists nearby.'}</p>${busy?'':'<button class="secondary" id="clear">Clear filters</button> <a href="tel:211">Call 211</a>'}</div>`;$('#clear')?.addEventListener('click',()=>{type='All';savedOnly=false;$('#keyword').value='';sources();$('#source-filter').value='All';sync();render()})}
function sync(){document.querySelectorAll('[data-type]').forEach(b=>{const active=b.dataset.type===type;b.classList.toggle('selected',active);b.setAttribute('aria-pressed',active)});$('#saved').setAttribute('aria-pressed',savedOnly)}
async function search(params,nextLabel){if(busy)return;busy=true;$('#address-choices').replaceChildren();hasSearched=true;loadError='';savedOnly=false;rows=[];truncated=false;sync();sources();$('#status').textContent='Searching the national food directory…';document.querySelectorAll('#location-form button').forEach(b=>b.disabled=true);$('#results').setAttribute('aria-busy','true');render();try{if(params.address){
 const response=await fetch('/api/geocode?q='+encodeURIComponent(params.address),{signal:AbortSignal.timeout(25000),credentials:'omit'});const data=await response.json();if(!response.ok)throw Error(data.error||'Address lookup unavailable. Try a ZIP.');if(!data.matches?.length)throw Error('No matching street address found. Add city and state, or search a ZIP code.');
 if(data.matches.length>1){const box=$('#address-choices');data.matches.forEach(m=>{const b=document.createElement('button');b.type='button';b.className='secondary address-choice';b.textContent=m.label;b.onclick=()=>search({lat:m.lat,lng:m.lng},m.label);box.append(b)});$('#status').textContent='Choose your matching address below the search box.';hasSearched=false;return;}
 params={lat:data.matches[0].lat,lng:data.matches[0].lng};nextLabel=data.matches[0].label;
}const url=new URL('/api/food',window.location.origin);Object.entries({...params,mode:'free',radius:5,limit:100}).forEach(([k,v])=>url.searchParams.set(k,v));const response=await fetch(url,{signal:AbortSignal.timeout(25000),credentials:'omit'});const data=await response.json();if(!response.ok)throw Error(data.error||'The directory could not be reached. Try again shortly.');if(data.success===false)throw Error(data.error||'Location was not found. Try a different ZIP.');const c=params.lat!=null?[Number(params.lat),Number(params.lng)]:[data.location?.lat,data.location?.lng];if(c.some(x=>x==null||!Number.isFinite(Number(x))))throw Error('ZIP location could not be found. Try another ZIP or use your location.');label=nextLabel;rows=normalize(data,c.map(Number));truncated=Number(data.total_available)>data.resources.length;sources();$('#status').textContent=`Search completed for ${label}. Only returned free-food listings within five miles are shown. ${data.expanded?'The source expanded its search; we removed listings outside your radius. ':''}Availability is not confirmed.`;}catch(e){loadError=e.name==='TimeoutError'?'Search timed out. Try again, or use a directory below.':e.message;$('#status').textContent=loadError;$('#count').textContent='Search unavailable';}finally{busy=false;document.querySelectorAll('#location-form button').forEach(b=>b.disabled=false);$('#results').setAttribute('aria-busy','false');render()}}
$('#location-form').onsubmit=e=>{e.preventDefault();if(busy)return;const value=$('#location').value.trim();if(/^\d{5}$/.test(value)){search({zip:value},'ZIP '+value);return}if(value.length<8||/^\d+$/.test(value)){$('#status').textContent='Enter a five-digit ZIP code or a street address with city and state.';return}search({address:value},value)};
$('#keyword').oninput=render;$('#source-filter').onchange=render;document.querySelectorAll('[data-type]').forEach(b=>b.onclick=()=>{type=b.dataset.type;sync();render()});$('#saved').onclick=()=>{savedOnly=!savedOnly;sources();sync();render()};$('#results').onclick=e=>{const b=e.target.closest('[data-save]');if(!b)return;const id=b.dataset.save;if(saved.some(r=>r.id===id))saved=saved.filter(r=>r.id!==id);else{const row=rows.find(r=>r.id===id);if(row)saved.push(row)}try{localStorage.setItem('fff-national-saved',JSON.stringify(saved));$('#status').textContent='Saved listings updated in this browser.'}catch{$('#status').textContent='Storage unavailable. Saved for this visit only.'}sources();render()};
$('#locate').onclick=()=>{if(busy)return;if(!navigator.geolocation){$('#status').textContent='Location unavailable. Enter a ZIP instead.';return}document.querySelectorAll('#location-form button').forEach(b=>b.disabled=true);$('#status').textContent='Waiting for location permission…';navigator.geolocation.getCurrentPosition(p=>{document.querySelectorAll('#location-form button').forEach(b=>b.disabled=false);search({lat:p.coords.latitude,lng:p.coords.longitude},'your location')},()=>{document.querySelectorAll('#location-form button').forEach(b=>b.disabled=false);$('#status').textContent='Location could not be accessed. Enter a ZIP instead.'},{timeout:12000,maximumAge:60000})};$('#print').onclick=()=>window.print();$('#status').textContent='Ready to search nationwide. Enter your address or ZIP code, or use your location.';render();
